  private redondearDecimales(num: number, margen: number = 0.005): number {
    num = +num; // Asegurarse de que num es un número
    const decimal = num - Math.floor(num); // Obtener la parte decimal

    // Redondear hacia arriba si la parte decimal es >= (1 - margen)
    if (decimal >= (1 - margen)) {
      return Math.ceil(num);
    }

    // Redondear hacia abajo si la parte decimal es < margen
    if (decimal < margen) {
      return Math.floor(num);
    }

    // De lo contrario, devolver el número original
    return num;
  }

  private formatCurrency = (value: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(value);
  };
